from strategies.base import register
from strategies.ema.strategy import EMAStrategy


@register("ema")
class RegisteredEMAStrategy(EMAStrategy):
    pass

from __future__ import annotations

from typing import Any

from strategies.base import load_strategy_defaults

_ema_defaults_cache: dict[str, Any] | None = None


def _load_ema_defaults() -> dict[str, Any]:
    raw = load_strategy_defaults("ema")
    return {k: v for k, v in raw.items() if k != "family"}


def _get_ema_defaults() -> dict[str, Any]:
    global _ema_defaults_cache
    if _ema_defaults_cache is None:
        _ema_defaults_cache = _load_ema_defaults()
    return _ema_defaults_cache

from __future__ import annotations

from dataclasses import dataclass
from typing import Any


@dataclass(frozen=True)
class CompilationResult:
    status: str
    runtime_config: dict[str, Any]
    missing_primitives: list[str]
    normalized_contract: list[dict[str, Any]]


REQUIRED_TYPES = {"ema_length", "timeframe_long", "timeframe_short", "risk_reward"}


def normalize_ema_contract(contract: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return [{k: v for k, v in primitive.items() if v is not None} for primitive in contract]
